enum class Status {
  Ok = 0,

  // Jwt errors:

  // Jwt missing.
  JwtMissed,

  // Jwt not valid yet.
  JwtNotYetValid,

  // Jwt expired.
  JwtExpired,

  // JWT is not in the form of Header.Payload.Signature
  JwtBadFormat,

  // Jwt header is an invalid Base64url encoded.
  JwtHeaderParseErrorBadBase64,

  // Jwt header is an invalid JSON.
  JwtHeaderParseErrorBadJson,

  // "alg" in the header is not a string.
  JwtHeaderBadAlg,

  // Value of "alg" in the header is invalid.
  JwtHeaderNotImplementedAlg,

  // "kid" in the header is not a string.
  JwtHeaderBadKid,

  // Jwt payload is an invalid Base64url encoded.
  JwtPayloadParseErrorBadBase64,

  // Jwt payload is an invalid JSON.
  JwtPayloadParseErrorBadJson,

  // Jwt payload field [iss] must be string.
  JwtPayloadParseErrorIssNotString,

  // Jwt payload field [sub] must be string.
  JwtPayloadParseErrorSubNotString,

  // Jwt payload field [iat] must be integer.
  JwtPayloadParseErrorIatNotInteger,

  // Jwt payload field [iat] must be within a 64 bit positive integer range.
  JwtPayloadParseErrorIatOutOfRange,

  // Jwt payload field [nbf] must be integer.
  JwtPayloadParseErrorNbfNotInteger,

  // Jwt payload field [nbf] must be within a 64 bit positive integer range.
  JwtPayloadParseErrorNbfOutOfRange,

  // Jwt payload field [exp] must be integer.
  JwtPayloadParseErrorExpNotInteger,

  // Jwt payload field [exp] must be within a 64 bit positive integer range.
  JwtPayloadParseErrorExpOutOfRange,

  // Jwt payload field [jti] must be string.
  JwtPayloadParseErrorJtiNotString,

  // Jwt payload field [aud] must be string or string list.
  JwtPayloadParseErrorAudNotString,

  // Jwt signature is an invalid Base64url input.
  JwtSignatureParseErrorBadBase64,

  // Jwt ED25519 signature is wrong length
  JwtEd25519SignatureWrongLength,

  // Issuer is not configured.
  JwtUnknownIssuer,

  // Audience is not allowed.
  JwtAudienceNotAllowed,

  // Jwt verification fails.
  JwtVerificationFail,

  // Found multiple Jwt tokens.
  JwtMultipleTokens,

  // Jwks errors

  // Jwks is an invalid JSON.
  JwksParseError,

  // Jwks does not have "keys".
  JwksNoKeys,

  // "keys" in Jwks is not an array.
  JwksBadKeys,

  // Jwks doesn't have any valid public key.
  JwksNoValidKeys,

  // Jwks doesn't have key to match kid or alg from Jwt.
  JwksKidAlgMismatch,

  // "n" or "e" field of a Jwk RSA is missing or has a parse error.
  JwksRsaParseError,

  // Failed to create a EC_KEY object.
  JwksEcCreateKeyFail,

  // "x" or "y" field is an invalid Base64
  JwksEcXorYBadBase64,

  // "x" or "y" field of a Jwk EC is missing or has a parse error.
  JwksEcParseError,

  // Jwks Oct key is an invalid Base64.
  JwksOctBadBase64,

  // "x" field is invalid Base64
  JwksOKPXBadBase64,
  // "x" field is wrong length
  JwksOKPXWrongLength,

  // Failed to fetch public key
  JwksFetchFail,

  // "kty" is missing in "keys".
  JwksMissingKty,
  // "kty" is not string type in "keys".
  JwksBadKty,
  // "kty" is not supported in "keys".
  JwksNotImplementedKty,

  // "alg" is not started with "RS" for a RSA key
  JwksRSAKeyBadAlg,
  // "n" field is missing for a RSA key
  JwksRSAKeyMissingN,
  // "n" field is not string for a RSA key
  JwksRSAKeyBadN,
  // "e" field is missing for a RSA key
  JwksRSAKeyMissingE,
  // "e" field is not string for a RSA key
  JwksRSAKeyBadE,

  // "alg" is not "ES256", "ES384" or "ES512" for an EC key
  JwksECKeyBadAlg,
  // "crv" field is not string for an EC key
  JwksECKeyBadCrv,
  // "crv" or "alg" is not supported for an EC key
  JwksECKeyAlgOrCrvUnsupported,
  // "crv" is not compatible with "alg" for an EC key
  JwksECKeyAlgNotCompatibleWithCrv,
  // "x" field is missing for an EC key
  JwksECKeyMissingX,
  // "x" field is not string for an EC key
  JwksECKeyBadX,
  // "y" field is missing for an EC key
  JwksECKeyMissingY,
  // "y" field is not string for an EC key
  JwksECKeyBadY,

  // "alg" is not "HS256", "HS384" or "HS512" for an HMAC key
  JwksHMACKeyBadAlg,
  // "k" field is missing for an HMAC key
  JwksHMACKeyMissingK,
  // "k" field is not string for an HMAC key
  JwksHMACKeyBadK,

  // "alg" is not "EdDSA" for an OKP key
  JwksOKPKeyBadAlg,
  // "crv" field is missing for an OKP key
  JwksOKPKeyMissingCrv,
  // "crv" field is not string for an OKP key
  JwksOKPKeyBadCrv,
  // "crv" is not supported for an OKP key
  JwksOKPKeyCrvUnsupported,
  // "x" field is missing for an OKP key
  JwksOKPKeyMissingX,
  // "x" field is not string for an OKP key
  JwksOKPKeyBadX,

  // X509 BIO_Write function fails
  JwksX509BioWriteError,
  // X509 parse pubkey fails
  JwksX509ParseError,
  // X509 get pubkey fails
  JwksX509GetPubkeyError,

  // Key type is not supported.
  JwksPemNotImplementedKty,
  // Unable to parse public key
  JwksPemBadBase64,
  // Failed to get raw ED25519 key from PEM
  JwksPemGetRawEd25519Error,

  // Failed to create BIO
  JwksBioAllocError,
};

class WithStatus {
 public:
  WithStatus() : status_(Status::Ok) {}

  /**
   * Get the current status.
   * @return the enum status.
   */
  Status getStatus() const { return status_; }

 protected:
  void updateStatus(Status status) {
    // Only keep the first failure
    if (status_ == Status::Ok) {
      status_ = status;
    }
  }

  void resetStatus(Status status) { status_ = status; }

 private:
  // The internal status.
  Status status_;
};

namespace google {
namespace jwt_verify {

class StructUtils {
 public:
  StructUtils(const ::google::protobuf::Struct& struct_pb);

  enum FindResult {
    OK = 0,
    MISSING,
    WRONG_TYPE,
    OUT_OF_RANGE,
  };

  FindResult GetString(const std::string& name, std::string* str_value);

  // Return error if the JSON value is not within a positive 64 bit integer
  // range. The decimals in the JSON value are dropped.
  FindResult GetUInt64(const std::string& name, uint64_t* int_value);

  FindResult GetDouble(const std::string& name, double* double_value);

  FindResult GetBoolean(const std::string& name, bool* bool_value);

  // Get string or list of string, designed to get "aud" field
  // "aud" can be either string array or string.
  // Try as string array, read it as empty array if doesn't exist.
  FindResult GetStringList(const std::string& name,
                           std::vector<std::string>* list);

  // Find the value with nested names.
  FindResult GetValue(const std::string& nested_names,
                      const google::protobuf::Value*& found);

 private:
  const ::google::protobuf::Struct& struct_pb_;
};

}  // namespace jwt_verify
}  // namespace google

enum FindResult {
    OK = 0,
    MISSING,
    WRONG_TYPE,
    OUT_OF_RANGE,
  };

class CheckAudience {
 public:
  // Construct the object with a list audiences from config.
  CheckAudience(const std::vector<std::string>& config_audiences);

  // Check any of jwt_audiences is matched with one of configurated ones.
  bool areAudiencesAllowed(const std::vector<std::string>& jwt_audiences) const;

  // check if config audiences is empty
  bool empty() const { return config_audiences_.empty(); }

 private:
  // configured audiences;
  std::set<std::string> config_audiences_;
};

namespace google {
namespace jwt_verify {

// Clock skew defaults to one minute.
constexpr uint64_t kClockSkewInSecond = 60;

/**
 * struct to hold a JWT data.
 */
struct Jwt {
  // entire jwt
  std::string jwt_;

  // header string
  std::string header_str_;
  // header base64_url encoded
  std::string header_str_base64url_;
  // header in Struct protobuf
  ::google::protobuf::Struct header_pb_;

  // payload string
  std::string payload_str_;
  // payload base64_url encoded
  std::string payload_str_base64url_;
  // payload in Struct protobuf
  ::google::protobuf::Struct payload_pb_;
  // signature string
  std::string signature_;
  // alg
  std::string alg_;
  // kid
  std::string kid_;
  // iss
  std::string iss_;
  // audiences
  std::vector<std::string> audiences_;
  // sub
  std::string sub_;
  // issued at
  uint64_t iat_ = 0;
  // not before
  uint64_t nbf_ = 0;
  // expiration
  uint64_t exp_ = 0;
  // JWT ID
  std::string jti_;

  /**
   * Standard constructor.
   */
  Jwt() {}
  /**
   * Copy constructor. The copy constructor is marked as explicit as the caller
   * should understand the copy operation is non-trivial as a complete
   * re-deserialization occurs.
   * @param rhs the instance to copy.
   */
  explicit Jwt(const Jwt& instance);

  /**
   * Copy Jwt instance.
   * @param rhs the instance to copy.
   * @return this
   */
  Jwt& operator=(const Jwt& rhs);

  /**
   * Parse Jwt from string text
   * @return the status.
   */
  Status parseFromString(const std::string& jwt);

  /*
   * Verify Jwt time constraint if specified
   * esp: expiration time, nbf: not before time.
   * @param now: is the current time in seconds since the unix epoch
   * @param clock_skew: the the clock skew in second.
   * @return the verification status.
   */
  Status verifyTimeConstraint(uint64_t now,
                              uint64_t clock_skew = kClockSkewInSecond) const;
};

}  // namespace jwt_verify
}  // namespace google

class Jwks : public WithStatus {
 public:
  // Format of public key.
  enum Type { JWKS, PEM };

  // Create from string
  static std::unique_ptr<Jwks> createFrom(const std::string& pkey, Type type);
  // Executes to createFrom with type=PEM and sets additional JWKS paramaters
  // not specified within the PEM.
  static std::unique_ptr<Jwks> createFromPem(const std::string& pkey,
                                             const std::string& kid,
                                             const std::string& alg);

  // Adds a key to this keyset.
  Status addKeyFromPem(const std::string& pkey, const std::string& kid,
                       const std::string& alg);

  // Struct for JSON Web Key
  struct Pubkey {
    std::string hmac_key_;
    std::string kid_;
    std::string kty_;
    std::string alg_;
    std::string crv_;
    bssl::UniquePtr<RSA> rsa_;
    bssl::UniquePtr<EC_KEY> ec_key_;
    std::string okp_key_raw_;
    bssl::UniquePtr<BIO> bio_;
    bssl::UniquePtr<X509> x509_;
  };
  typedef std::unique_ptr<Pubkey> PubkeyPtr;

  // Access to list of Jwks
  const std::vector<PubkeyPtr>& keys() const { return keys_; }

 private:
  // Create Jwks
  void createFromJwksCore(const std::string& pkey_jwks);
  // Create PEM
  void createFromPemCore(const std::string& pkey_pem);

  // List of Jwks
  std::vector<PubkeyPtr> keys_;
};

struct Pubkey {
  std::string hmac_key_;
