    ::google::protobuf::ListValue* lv = v.mutable_list_value();
    int n = static_cast<int>(((seed >> (i + 11)) % 3u)); // 0..2 entries
    for (int j = 0; j < n; ++j) {
      ::google::protobuf::Value* elem = lv->add_values();
      std::string e = key_base;
      e.append("_e").append(std::to_string(j));
